import imageio.v2 as imageio
from PIL import Image,ImageDraw
r=imageio.get_reader('/app/output/submission_review.mp4')
for name,steps in [('pickup_review',[1,25,45,65,85,105,125,145,165]),('placement_review',[325,365,385,405,425,455,485,525,609])]:
 canvas=Image.new('RGB',(960,780),'white')
 for k,step in enumerate(steps):
  index=(step-1)//2
  frame=Image.fromarray(r.get_data(index)).resize((320,240))
  x,y=k%3*320,k//3*260
  canvas.paste(frame,(x,y));ImageDraw.Draw(canvas).text((x+7,y+244),f'Step {step} | {step/20:.2f} s',fill='black')
 canvas.save('/app/output/'+name+'.png')
r.close()
